import{_ as r,a0 as n,w as o,s as l,I as e,x as a,a1 as s,A as d,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const D=JSON.parse('{"title":"如何在 Ubuntu 上使用 ADB 备份 Android 数据 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上使用 ADB 备份 Android 数据 | LCTT (201702) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上使用 ADB 备份 Android 数据 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上使用 ADB 备份 Android 数据 | LCTT (201702) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201702/20170213 How to Back Up Your Android Data with ADB on Ubuntu","title":"如何在 Ubuntu 上使用 ADB 备份 Android 数据","tag":"201702","desc":""},"relativePath":"201702/20170213 How to Back Up Your Android Data with ADB on Ubuntu.md","filePath":"[post].md"}'),p={name:"201702/20170213 How to Back Up Your Android Data with ADB on Ubuntu.md"};function b(h,t,g,k,m,A){const i=n("Link");return o(),l("div",null,[t[16]||(t[16]=e("h1",{id:"如何在-ubuntu-上使用-adb-备份-android-数据",tabindex:"-1"},[a("如何在 Ubuntu 上使用 ADB 备份 Android 数据 "),e("a",{class:"header-anchor",href:"#如何在-ubuntu-上使用-adb-备份-android-数据","aria-label":"Permalink to “如何在 Ubuntu 上使用 ADB 备份 Android 数据”"},"​")],-1)),t[17]||(t[17]=e("p",null,[e("img",{src:"https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/android-backup-ubuntu.jpg",alt:"",title:"How to Back Up Your Android Data with ADB on Ubuntus"})],-1)),t[18]||(t[18]=e("p",null,"备份 Android 系统上的应用数据、文本信息等等是非常乏味的，有时还很昂贵。电子市场的许多应用都承诺可以备份数据，但效果不佳或者需要付昂贵费用。你是否知道有一种更好的方法可以来做这件事，并且在你的电脑上就可以完成？",-1)),t[19]||(t[19]=e("p",null,[a("Android 自带一套开发工具。有许多种开发工具，但人们最为感兴趣的项目是 ADB（或者叫做 "),e("ruby",null,[a("Android 调试桥"),e("rt",null," Android Debug Bridge")]),a("）。它允许用户通过命令行直接访问任何 Android 设备。有了这个工具，一切皆有可能 - 包括备份整个 Android 设备。在这篇文章中，将讨论如何在 Ubuntu 系统上完成这件事。")],-1)),e("p",null,[t[1]||(t[1]=e("strong",null,"注",-1)),t[2]||(t[2]=a("：这篇教程是针对 Ubuntu Linux 系统的。不过， ADB 在 Windows 系统和 Mac 上也是可用的，也可以在这些平台上对 Android 数据进行备份。",-1)),s(i,{href:"https://developer.android.com/studio/command-line/adb.html"},{default:d(()=>[...t[0]||(t[0]=[a("下载针对 Windows 和 Mac 的 ADB 版本。",-1)])]),_:1})]),t[20]||(t[20]=u('<h3 id="安装-adb-并启用-usb-调试" tabindex="-1">安装 ADB 并启用 USB 调试 <a class="header-anchor" href="#安装-adb-并启用-usb-调试" aria-label="Permalink to “安装 ADB 并启用 USB 调试”">​</a></h3><p>打开一个终端窗口，然后输入下面的命令来安装 ADB，它将与 Android 进行会话。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install adb</span></span></code></pre></div><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/adb-install-adb-ubuntu.jpg" alt="adb-install-adb-ubuntu" title="adb-install-adb-ubuntu"></p><p>在系统上安装好 ADB 工具以后，需要在 Android 内部启动调试。首先打开 Android 的<ruby>设置<rt>Settings</rt></ruby>区域。然后一直滚动到底部找到“<ruby>关于手机<rt>About Phone</rt></ruby>”并点击。这将打开“<ruby>电话状态<rt>Phone status</rt></ruby>”页。在这一页面上再次滚动到底部，找到“<ruby>版本号<rt>Build number</rt></ruby>”并点击七次，从而启动开发者模式。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/adb-about-phone.jpg" alt="adb-about-phone" title="adb-about-phone"></p><p>为了进入<ruby>开发者设置<rt>Developer Settings</rt></ruby>，按设备上的返回键返回上一页面。在“设置”中将会出现一个新的选项：“<ruby>开发者选项<rt>Developer options</rt></ruby>”。点击它进入开发者设置区域。滚动页面直到看到 “<ruby>Android 调试<rt>Android debugging</rt></ruby>”（或它的一些其他名称），点击它启用设置。</p><h3 id="备份" tabindex="-1">备份 <a class="header-anchor" href="#备份" aria-label="Permalink to “备份”">​</a></h3><p>使用 ADB 创建一个备份就如同运行一个命令一样简单。首先，用一根与 Android 设备匹配的 USB 线将 Android 设备连接到电脑上。然后打开终端运行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>adb start-server</span></span></code></pre></div><p>这将启动 ADB 服务器。运行这个命令时，要快速解锁 Android 设备，因为 ADB 将强制出现一个确认窗口，必须选择接受后才可继续。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/adb-all-usb-debugging.jpg" alt="adb-all-usb-debugging" title="adb-all-usb-debugging"></p><p>要启动备份进程，打开终端，然后执行下面的备份命令。该命令将读取 Android 上的文本信息以及其他应用数据，然后存入加密文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>adb backup -apk -shared -all -f backup-file.adb</span></span></code></pre></div><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/adb-full-backup.jpg" alt="adb-full-backup" title="adb-full-backup"></p><p>当运行备份命令时，Android 会在启动备份进程前提示用户查看 Android 并设置加密文件的密码。请输入一个强壮而容易记住的密码。然后，点击“备份我的数据”按钮。备份过程将会花费一定时间。备份完成以后，在目录 <code>/home/username/</code> 中会出现一个叫做 <code>backup-file.adb</code> 的文件。</p><h3 id="恢复备份" tabindex="-1">恢复备份 <a class="header-anchor" href="#恢复备份" aria-label="Permalink to “恢复备份”">​</a></h3><p>要恢复备份，首先启用 ADB 服务器（像上面提到的一样），然后运行下面这个命令来还原备份数据：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>adb restore backup-file.adb</span></span></code></pre></div><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2017/02/adb-full-restore.jpg" alt="adb-full-restore" title="adb-full-restore"></p><p>再次转到 Android， 因为 ADB 将提示用户输入密码。这次，不是创建一个密码，而是需要输入之前创建的那个密码。在点击 “<ruby>恢复我的数据<rt>restore my data</rt></ruby>” 以后，恢复进程就开始了。耐心点，因为这可能需要一定时间。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>没有多少 Android 用户知道这样备份数据，但是 ADB 的确很强大。利用它甚至可以获得对设备的 root 访问。事实上，利用这个工具还可以做很多的事情，需要更多的文章来讨论它。</p><p>你还知道 ADB 可以用来干什么吗？请在下面的评论区告知我们！</p><hr>',25)),e("p",null,[t[4]||(t[4]=a("via: ",-1)),s(i,{href:"https://www.maketecheasier.com/back-up-android-data-adb-ubuntu/"},{default:d(()=>[...t[3]||(t[3]=[a("https://www.maketecheasier.com/back-up-android-data-adb-ubuntu/",-1)])]),_:1})]),e("p",null,[t[8]||(t[8]=a("作者：",-1)),s(i,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:d(()=>[...t[5]||(t[5]=[a("Derrik Diener",-1)])]),_:1}),t[9]||(t[9]=a(" 译者：",-1)),s(i,{href:"https://github.com/ucasFL"},{default:d(()=>[...t[6]||(t[6]=[a("ucasFL",-1)])]),_:1}),t[10]||(t[10]=a(" 校对：",-1)),s(i,{href:"https://github.com/jasminepeng"},{default:d(()=>[...t[7]||(t[7]=[a("jasminepeng",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=a("本文由 ",-1)),s(i,{href:"https://github.com/LCTT/TranslateProject"},{default:d(()=>[...t[11]||(t[11]=[a("LCTT",-1)])]),_:1}),t[14]||(t[14]=a(" 原创编译，",-1)),s(i,{href:"https://linux.cn/"},{default:d(()=>[...t[12]||(t[12]=[a("Linux中国",-1)])]),_:1}),t[15]||(t[15]=a(" 荣誉推出",-1))])])}const B=r(p,[["render",b]]);export{D as __pageData,B as default};
